-- ReturnDesk schema. Idempotent: safe to run repeatedly.

CREATE SEQUENCE IF NOT EXISTS request_ref_seq;

CREATE TABLE IF NOT EXISTS return_requests (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- Human-readable reference generated by the database, e.g. RD-000042.
  reference      text NOT NULL UNIQUE
                 DEFAULT ('RD-' || lpad(nextval('request_ref_seq')::text, 6, '0')),
  customer_name  text NOT NULL CHECK (length(btrim(customer_name)) > 0),
  customer_email text NOT NULL CHECK (length(btrim(customer_email)) > 0),
  customer_phone text,
  order_number   text NOT NULL CHECK (length(btrim(order_number)) > 0),
  item_sku       text NOT NULL CHECK (length(btrim(item_sku)) > 0),
  item_name      text NOT NULL CHECK (length(btrim(item_name)) > 0),
  quantity       integer NOT NULL CHECK (quantity > 0),
  reason         text NOT NULL
                 CHECK (reason IN ('DAMAGED','WRONG_ITEM','SIZE_ISSUE','NOT_AS_DESCRIBED','CHANGED_MIND')),
  status         text NOT NULL DEFAULT 'OPEN'
                 CHECK (status IN ('OPEN','IN_REVIEW','APPROVED','REJECTED','COMPLETED')),
  resolution     text CHECK (resolution IN ('REFUND','REPLACEMENT','STORE_CREDIT')),
  refund_amount  numeric(10,2),
  deleted_at     timestamptz,                      -- soft delete: row is never destroyed
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),

  -- Approved/Completed requests must carry a resolution; no one else may.
  CONSTRAINT resolution_matches_status
    CHECK ((status IN ('APPROVED','COMPLETED')) = (resolution IS NOT NULL)),
  -- Refund needs an amount > 0; any other resolution must have no amount.
  CONSTRAINT refund_amount_rules
    CHECK (
      (resolution = 'REFUND' AND COALESCE(refund_amount > 0, false))
      OR (resolution IS DISTINCT FROM 'REFUND' AND refund_amount IS NULL)
    )
);

-- Rule 3: one live request per order + item. A partial unique index makes the
-- database itself refuse duplicates, even under concurrent requests.
CREATE UNIQUE INDEX IF NOT EXISTS uniq_live_request_per_order_item
  ON return_requests (lower(btrim(order_number)), lower(btrim(item_sku)))
  WHERE deleted_at IS NULL AND status NOT IN ('REJECTED','COMPLETED');

CREATE INDEX IF NOT EXISTS idx_requests_status     ON return_requests (status)     WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_requests_reason     ON return_requests (reason)     WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_requests_created_at ON return_requests (created_at) WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS request_notes (
  id         bigserial PRIMARY KEY,
  request_id uuid NOT NULL REFERENCES return_requests(id),
  body       text NOT NULL CHECK (length(btrim(body)) > 0),
  author     text NOT NULL DEFAULT 'Agent',
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_notes_request ON request_notes (request_id, created_at, id);

-- Notes are append-only: the database refuses edits and deletes.
CREATE OR REPLACE FUNCTION forbid_note_changes() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'request_notes is append-only';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS request_notes_append_only ON request_notes;
CREATE TRIGGER request_notes_append_only
  BEFORE UPDATE OR DELETE ON request_notes
  FOR EACH ROW EXECUTE FUNCTION forbid_note_changes();
